package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringUtils.indexOfAny(CharSequence cs, char[] searchChars)
 */
public class StringUtils_indexOfAny_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        char[] searchChars = {'a', 'b', 'c'};
        assertEquals(0, StringUtils.indexOfAny("abcde", searchChars));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        char[] searchChars = {'x', 'y', 'z'};
        assertEquals(2, StringUtils.indexOfAny("abxde", searchChars));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        char[] searchChars = {'e', 'f'};
        assertEquals(4, StringUtils.indexOfAny("abcde", searchChars));
    }

    @Test
    public void testIndexOfAny_MultipleMatchesReturnsFirstOccurrence() {
        // The method iterates through cs first, so it returns the index of the first char in cs that matches any in searchChars
        char[] searchChars = {'e', 'b'};
        assertEquals(1, StringUtils.indexOfAny("abcde", searchChars));
    }

    @Test
    public void testIndexOfAny_NoMatch() {
        char[] searchChars = {'1', '2', '3'};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abcde", searchChars));
    }

    @Test
    public void testIndexOfAny_SingleCharSearch() {
        char[] searchChars = {'c'};
        assertEquals(2, StringUtils.indexOfAny("abcde", searchChars));
    }

    @Test
    public void testIndexOfAny_SupplementaryCharacters() {
        // Testing behavior with characters that might be treated as single units in higher level APIs
        // though the method logic works on char primitives.
        String cs = "a\uD83D\uDE00b"; // a, Grinning Face, b
        char[] searchChars = {'\uDE00'}; // The low surrogate
        // Since the loop checks cs.charAt(i), it will find the low surrogate at index 2
        assertEquals(2, StringUtils.indexOfAny(cs, searchChars));
    }
}
